// Get all rows returned by Google Sheets
const rows = $input.all().map(item => item.json);

if (!rows.length) {
  return [{
    json: {
      error: "No ecommerce records were found."
    }
  }];
}

// ---------- Helper functions ----------

function findColumn(possibleNames) {
  const keys = Object.keys(rows[0]);

  return keys.find(key =>
    possibleNames.some(name =>
      key.toLowerCase().trim() === name.toLowerCase().trim()
    )
  );
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;

  const cleaned = String(value)
    .replace(/₹/g, '')
    .replace(/,/g, '')
    .replace(/%/g, '')
    .trim();

  const number = Number(cleaned);

  return Number.isFinite(number) ? number : 0;
}

// ---------- Detect columns ----------

const orderIdCol = findColumn([
  'Order ID',
  'OrderID',
  'Order_Id',
  'order_id'
]);

const orderDateCol = findColumn([
  'Order Date',
  'OrderDate',
  'Order_Date',
  'date',
  'Date'
]);

const customerCol = findColumn([
  'Customer ID',
  'CustomerID',
  'Customer_Id',
  'customer_id'
]);

const productCol = findColumn([
  'Product',
  'Product Name',
  'ProductName',
  'Product ID',
  'ProductID'
]);

const categoryCol = findColumn([
  'Category',
  'Product Category'
]);

const subCategoryCol = findColumn([
  'Sub-Category',
  'Sub Category',
  'SubCategory'
]);

const regionCol = findColumn([
  'Region',
  'Sales Region'
]);

const quantityCol = findColumn([
  'Quantity',
  'Qty'
]);

const salesCol = findColumn([
  'Sales',
  'Revenue',
  'Amount',
  'Total Sales'
]);

const profitCol = findColumn([
  'Profit',
  'Net Profit'
]);

// ---------- Basic KPIs ----------

const totalRevenue = salesCol
  ? rows.reduce((sum, row) => sum + toNumber(row[salesCol]), 0)
  : null;

const totalProfit = profitCol
  ? rows.reduce((sum, row) => sum + toNumber(row[profitCol]), 0)
  : null;

const totalQuantity = quantityCol
  ? rows.reduce((sum, row) => sum + toNumber(row[quantityCol]), 0)
  : null;

const uniqueOrders = orderIdCol
  ? new Set(
      rows
        .map(row => row[orderIdCol])
        .filter(value => value !== null && value !== undefined && value !== '')
    ).size
  : rows.length;

const uniqueCustomers = customerCol
  ? new Set(
      rows
        .map(row => row[customerCol])
        .filter(value => value !== null && value !== undefined && value !== '')
    ).size
  : null;

const averageOrderValue =
  totalRevenue !== null && uniqueOrders
    ? totalRevenue / uniqueOrders
    : null;

const profitMargin =
  totalRevenue && totalProfit !== null
    ? (totalProfit / totalRevenue) * 100
    : null;

// ---------- Grouping helper ----------

function groupBy(column, valueColumn) {
  if (!column || !valueColumn) return [];

  const groups = {};

  for (const row of rows) {
    const group = String(row[column] ?? 'Unknown').trim() || 'Unknown';

    if (!groups[group]) {
      groups[group] = {
        name: group,
        revenue: 0,
        profit: 0,
        quantity: 0,
        records: 0
      };
    }

    groups[group].revenue += toNumber(row[salesCol]);

    if (profitCol) {
      groups[group].profit += toNumber(row[profitCol]);
    }

    if (quantityCol) {
      groups[group].quantity += toNumber(row[quantityCol]);
    }

    groups[group].records++;
  }

  return Object.values(groups)
    .map(item => ({
      ...item,
      profitMargin:
        item.revenue !== 0
          ? (item.profit / item.revenue) * 100
          : 0
    }))
    .sort((a, b) => b.revenue - a.revenue);
}

// ---------- Product analysis ----------

let topProducts = [];

if (productCol && salesCol) {
  topProducts = groupBy(productCol, salesCol)
    .slice(0, 10);
}

// ---------- Category analysis ----------

let categories = [];

if (categoryCol && salesCol) {
  categories = groupBy(categoryCol, salesCol);
}

// ---------- Region analysis ----------

let regions = [];

if (regionCol && salesCol) {
  regions = groupBy(regionCol, salesCol);
}

// ---------- Monthly analysis ----------

let monthly = [];

if (orderDateCol && salesCol) {

  const monthGroups = {};

  for (const row of rows) {

    const rawDate = row[orderDateCol];

    if (!rawDate) continue;

    const date = new Date(rawDate);

    if (isNaN(date.getTime())) continue;

    const monthKey =
      `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;

    if (!monthGroups[monthKey]) {
      monthGroups[monthKey] = {
        month: monthKey,
        revenue: 0,
        profit: 0,
        records: 0
      };
    }

    monthGroups[monthKey].revenue += toNumber(row[salesCol]);

    if (profitCol) {
      monthGroups[monthKey].profit += toNumber(row[profitCol]);
    }

    monthGroups[monthKey].records++;
  }

  monthly = Object.values(monthGroups)
    .sort((a, b) => a.month.localeCompare(b.month))
    .map(item => ({
      ...item,
      profitMargin:
        item.revenue !== 0
          ? (item.profit / item.revenue) * 100
          : 0
    }));
}

// ---------- Data quality ----------

const missingValues = {};

for (const column of Object.keys(rows[0])) {

  const missing = rows.filter(row =>
    row[column] === null ||
    row[column] === undefined ||
    String(row[column]).trim() === ''
  ).length;

  if (missing > 0) {
    missingValues[column] = missing;
  }
}

// Duplicate rows
const rowStrings = rows.map(row => JSON.stringify(row));
const duplicateCount = rowStrings.length - new Set(rowStrings).size;

// ---------- Get user's original question ----------

let userQuestion = '';

try {
  userQuestion =
    $('When chat message received').first().json.chatInput || '';
} catch (error) {
  userQuestion = '';
}

// ---------- Final compact output ----------

return [{
  json: {

    userQuestion,

    dataset: {
      rows: rows.length,
      columns: Object.keys(rows[0]),
      detectedColumns: {
        orderId: orderIdCol,
        orderDate: orderDateCol,
        customer: customerCol,
        product: productCol,
        category: categoryCol,
        subCategory: subCategoryCol,
        region: regionCol,
        quantity: quantityCol,
        sales: salesCol,
        profit: profitCol
      }
    },

    kpis: {
      totalRevenue,
      totalProfit,
      totalQuantity,
      totalOrders: uniqueOrders,
      totalCustomers: uniqueCustomers,
      averageOrderValue,
      profitMargin
    },

    topProducts,

    categories,

    regions,

    monthly,

    dataQuality: {
      duplicateRows: duplicateCount,
      missingValues
    }
  }
}];

const rows = $input.all().map(item => item.json);

if (!rows.length) {
  return [
    {
      json: {
        dataset: {
          rows: 0,
          columns: []
        },
        kpis: {},
        topProducts: [],
        categories: [],
        regions: [],
        monthly: [],
        dataQuality: {}
      }
    }
  ];
}

// ---------- Helper functions ----------

function findColumn(possibleNames) {
  const columns = Object.keys(rows[0] || {});

  return columns.find(col =>
    possibleNames.some(name =>
      col.toLowerCase().trim() === name.toLowerCase().trim()
    )
  );
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 0;
  }

  const num = Number(String(value).replace(/,/g, ''));

  return Number.isFinite(num) ? num : 0;
}

function round(value, decimals = 2) {
  return Number(Number(value || 0).toFixed(decimals));
}

// ---------- Detect columns ----------

const orderIdCol = findColumn([
  'Order ID',
  'OrderID',
  'Order_Id',
  'order_id'
]);

const orderDateCol = findColumn([
  'Order Date',
  'OrderDate',
  'Order_Date',
  'Date',
  'date'
]);

const customerIdCol = findColumn([
  'Customer ID',
  'CustomerID',
  'Customer_Id',
  'customer_id'
]);

const productCol = findColumn([
  'Product',
  'Product Name',
  'ProductName',
  'Product ID',
  'ProductID'
]);

const categoryCol = findColumn([
  'Category',
  'Product Category'
]);

const subCategoryCol = findColumn([
  'Sub-Category',
  'Sub Category',
  'SubCategory'
]);

const regionCol = findColumn([
  'Region',
  'Sales Region'
]);

const quantityCol = findColumn([
  'Quantity',
  'Qty'
]);

const salesCol = findColumn([
  'Sales',
  'Revenue',
  'Amount',
  'Total Sales'
]);

const profitCol = findColumn([
  'Profit',
  'Net Profit'
]);

// ---------- Basic KPI calculations ----------

const totalRevenue = rows.reduce(
  (sum, row) => sum + toNumber(row[salesCol]),
  0
);

const totalProfit = rows.reduce(
  (sum, row) => sum + toNumber(row[profitCol]),
  0
);

const totalQuantity = rows.reduce(
  (sum, row) => sum + toNumber(row[quantityCol]),
  0
);

const orderIds = new Set(
  rows
    .map(row => row[orderIdCol])
    .filter(value => value !== undefined && value !== null && value !== '')
);

const customerIds = new Set(
  rows
    .map(row => row[customerIdCol])
    .filter(value => value !== undefined && value !== null && value !== '')
);

const totalOrders = orderIds.size || rows.length;

const totalCustomers = customerIds.size;

const averageOrderValue =
  totalOrders > 0
    ? totalRevenue / totalOrders
    : 0;

const profitMargin =
  totalRevenue !== 0
    ? (totalProfit / totalRevenue) * 100
    : 0;

// ---------- Grouping helper ----------

function groupBy(column) {
  const groups = {};

  if (!column) return [];

  for (const row of rows) {
    const key = row[column];

    if (
      key === undefined ||
      key === null ||
      String(key).trim() === ''
    ) {
      continue;
    }

    const name = String(key).trim();

    if (!groups[name]) {
      groups[name] = {
        name,
        revenue: 0,
        profit: 0,
        quantity: 0
      };
    }

    groups[name].revenue += toNumber(row[salesCol]);
    groups[name].profit += toNumber(row[profitCol]);
    groups[name].quantity += toNumber(row[quantityCol]);
  }

  return Object.values(groups)
    .map(item => ({
      ...item,
      revenue: round(item.revenue),
      profit: round(item.profit),
      quantity: round(item.quantity),
      profitMargin:
        item.revenue !== 0
          ? round((item.profit / item.revenue) * 100)
          : 0
    }))
    .sort((a, b) => b.revenue - a.revenue);
}

// ---------- Product performance ----------

const productGroups = groupBy(productCol);

const topProducts = productGroups
  .slice(0, 10);

// ---------- Category performance ----------

const categories = groupBy(categoryCol);

// ---------- Regional performance ----------

const regions = groupBy(regionCol);

// ---------- Monthly performance ----------

const monthlyGroups = {};

if (orderDateCol) {

  for (const row of rows) {

    const rawDate = row[orderDateCol];

    if (!rawDate) continue;

    const date = new Date(rawDate);

    if (isNaN(date.getTime())) continue;

    const year = date.getFullYear();

    const month = date.getMonth() + 1;

    const key =
      `${year}-${String(month).padStart(2, '0')}`;

    if (!monthlyGroups[key]) {
      monthlyGroups[key] = {
        month: key,
        revenue: 0,
        profit: 0,
        quantity: 0
      };
    }

    monthlyGroups[key].revenue += toNumber(row[salesCol]);
    monthlyGroups[key].profit += toNumber(row[profitCol]);
    monthlyGroups[key].quantity += toNumber(row[quantityCol]);
  }
}

const monthly = Object.values(monthlyGroups)
  .map(item => ({
    month: item.month,
    revenue: round(item.revenue),
    profit: round(item.profit),
    quantity: round(item.quantity),
    profitMargin:
      item.revenue !== 0
        ? round((item.profit / item.revenue) * 100)
        : 0
  }))
  .sort((a, b) => a.month.localeCompare(b.month));

// ---------- Duplicate detection ----------

const rowSignatures = new Set();

let duplicateRows = 0;

for (const row of rows) {

  const signature = JSON.stringify(row);

  if (rowSignatures.has(signature)) {
    duplicateRows++;
  } else {
    rowSignatures.add(signature);
  }
}

// ---------- Missing values ----------

const missingValues = {};

for (const column of Object.keys(rows[0] || {})) {

  const missing = rows.filter(row =>
    row[column] === undefined ||
    row[column] === null ||
    String(row[column]).trim() === ''
  ).length;

  if (missing > 0) {
    missingValues[column] = missing;
  }
}

// ---------- Final reporting object ----------

const report = {

  dataset: {
    rows: rows.length,
    columns: Object.keys(rows[0] || {}).length,
    columnNames: Object.keys(rows[0] || {})
  },

  detectedColumns: {
    orderId: orderIdCol,
    orderDate: orderDateCol,
    customerId: customerIdCol,
    product: productCol,
    category: categoryCol,
    subCategory: subCategoryCol,
    region: regionCol,
    quantity: quantityCol,
    sales: salesCol,
    profit: profitCol
  },

  kpis: {
    totalRevenue: round(totalRevenue),
    totalProfit: round(totalProfit),
    profitMargin: round(profitMargin),
    totalOrders,
    totalCustomers,
    averageOrderValue: round(averageOrderValue),
    totalQuantity: round(totalQuantity)
  },

  topProducts,

  categories,

  regions,

  monthly,

  dataQuality: {
    duplicateRows,
    missingValues
  }
};

return [
  {
    json: report
  }
];
